"""What counts as pairing HISTORY (Kerry 2026-09-08).

"For the pairings, you're not counting pairings generated by the app that
were never used right? At the moment final GG pairings is what rules."

We were. Saving a sheet writes source='app' rows immediately, so a
grouping the app merely PROPOSED scored the same as one that teed off —
and a sheet saved for a future event made the generator treat pairs it
had just proposed as repeats, so hitting Generate twice fought its own
first answer.

Two rules, pinned here:
  1. Golf Genius rules. Where an event has GG rows they are the record
     and its app rows are ignored. Where it has none, the app rows are
     the only account of what happened and still count.
  2. Nothing dated in the future counts at all.

Run: python3 test_pairing_history_rule.py
"""

import os
import sys
import tempfile
from datetime import timedelta

os.environ.setdefault("DATABASE_PATH", ":memory:")

from email_parser import database as db  # noqa: E402
from email_parser.timezone_utils import today_central  # noqa: E402

FAILURES = []


def check(label, cond, detail=""):
    print(("  PASS  " if cond else "  FAIL  ") + label
          + ("" if cond else "  " + str(detail)))
    if not cond:
        FAILURES.append(label)


def add(conn, a, b, event_id, date, source):
    conn.execute(
        "INSERT INTO pairing_history (player_a, player_b, event_id, "
        "event_date, rode, source) VALUES (?,?,?,?,0,?)",
        (min(a, b), max(a, b), event_id, date, source))


def main():
    tmp = tempfile.NamedTemporaryFile(suffix=".db", delete=False)
    tmp.close()
    p = tmp.name
    today = today_central()
    past = (today - timedelta(days=7)).strftime("%Y-%m-%d")
    past2 = (today - timedelta(days=14)).strftime("%Y-%m-%d")
    future = (today + timedelta(days=7)).strftime("%Y-%m-%d")
    yr = today.year

    with db._connect(p) as conn:
        db._ensure_pairing_tables(conn)
        # Event 1, played: GG has it AND the app proposed something else.
        # GG rules — the app pair must not count.
        add(conn, "Ann Real", "Bob Real", 1, past, "gg_teesheet")
        add(conn, "Ann Real", "Cal Proposed", 1, past, "app")
        # Event 2, played, GG never ingested: the app rows are the only
        # record of what happened, so they count.
        add(conn, "Dee Only", "Eve Only", 2, past2, "app")
        # Event 3, NOT YET PLAYED: saved in the app. A plan, not history.
        add(conn, "Fay Future", "Gus Future", 3, future, "app")
        # Event 4, not yet played, and somehow GG-sourced: still future.
        add(conn, "Hal Future", "Ivy Future", 4, future, "gg_teesheet")
        conn.commit()

    counts = db.get_pairing_history_counts(year=yr, db_path=p)

    def n(a, b):
        a, b = db._pair_key_name(a), db._pair_key_name(b)
        return counts.get((min(a, b), max(a, b)), 0)

    check("a GG pair on a played event counts",
          n("Ann Real", "Bob Real") == 1, counts)
    check("an APP pair is ignored when GG has that event "
          "(final GG pairings rule)",
          n("Ann Real", "Cal Proposed") == 0, counts)
    check("an APP pair still counts when GG never ingested that event — "
          "it is the only record of what happened",
          n("Dee Only", "Eve Only") == 1, counts)
    check("a pairing saved for a FUTURE event never counts",
          n("Fay Future", "Gus Future") == 0, counts)
    check("... not even a GG-sourced future one",
          n("Hal Future", "Ivy Future") == 0, counts)
    check("nothing else leaked in", len(counts) == 2, counts)

    # The regression that started it: save a sheet, regenerate, and the
    # generator must not treat its own proposal as a prior play.
    with db._connect(p) as conn:
        add(conn, "Jan Same", "Kim Same", 3, future, "app")
        conn.commit()
    counts2 = db.get_pairing_history_counts(year=yr, db_path=p)
    check("re-generating an unplayed event does not fight its own save",
          counts2 == counts, counts2)

    print()
    if FAILURES:
        print(f"{len(FAILURES)} FAILED: " + ", ".join(FAILURES))
        sys.exit(1)
    print("All checks passed.")


if __name__ == "__main__":
    main()
